function isObject(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

function pickCondition(target, options = {}) {
  if (typeof target === 'string') {
    return target;
  }

  if (Array.isArray(target)) {
    for (const entry of target) {
      const resolved = pickCondition(entry, options);
      if (resolved !== undefined) {
        return resolved;
      }
    }
    return undefined;
  }

  if (!isObject(target)) {
    return undefined;
  }

  const candidates = [];
  if (options.browser) {
    candidates.push('browser');
  }
  if (Array.isArray(options.conditions)) {
    candidates.push(...options.conditions);
  }
  candidates.push('import', 'module', 'default', 'require');

  for (const key of candidates) {
    if (Object.prototype.hasOwnProperty.call(target, key)) {
      const resolved = pickCondition(target[key], options);
      if (resolved !== undefined) {
        return resolved;
      }
    }
  }

  return undefined;
}

export function exports(manifest, subpath = '.', options = {}) {
  if (!isObject(manifest) || manifest.exports == null) {
    return undefined;
  }

  const root = manifest.exports;
  let target = undefined;

  if (typeof root === 'string' || Array.isArray(root)) {
    target = root;
  } else if (isObject(root)) {
    if (Object.prototype.hasOwnProperty.call(root, subpath)) {
      target = root[subpath];
    } else if (subpath === '.' && !Object.keys(root).some((key) => key.startsWith('.'))) {
      target = root;
    }
  }

  return pickCondition(target, options);
}

export function legacy(manifest, options = {}) {
  if (!isObject(manifest)) {
    return undefined;
  }

  if (options.browser && typeof manifest.browser === 'string' && manifest.browser) {
    return manifest.browser;
  }

  const fields = Array.isArray(options.fields) && options.fields.length > 0 ? options.fields : ['module', 'main'];
  for (const field of fields) {
    if (typeof manifest[field] === 'string' && manifest[field]) {
      return manifest[field];
    }
  }

  if (typeof manifest.browser === 'string' && manifest.browser) {
    return manifest.browser;
  }

  return undefined;
}
